import cadquery as cq
import math

# Core dimensions (max 100 units)
worm_length = 60.0
worm_radius = 18.0
tooth_depth = 2.0
tooth_width = 6.0
pocket_width = 12.0
pocket_depth = 5.0
top_hole_diameter = 3.0
top_hole_radius = 12.0
chamfer_distance = 0.8

# Base cylinder representing the worm body
base_cylinder = (
    cq.Workplane("XY")
    .circle(worm_radius - tooth_depth)
    .extrude(worm_length)
)

# Single helical tooth generated by twistExtrude of a rectangular profile
tooth = (
    cq.Workplane("XY")
    .center(worm_radius - tooth_depth, 0)
    .rect(tooth_width, tooth_depth)
    .twistExtrude(worm_length, 360)
)

# Combine body and tooth
worm_body = base_cylinder.union(tooth)

# Final part with lubrication pocket, patterned top holes, and chamfer
result = (
    worm_body
    .cut(
        cq.Workplane()
        .box(pocket_width, worm_length, pocket_depth)
        .translate((worm_radius - pocket_width/2, 0, worm_length/2))
    )
    .faces(">Z")
    .workplane()
    .rarray(top_hole_radius, 0, 15, 1)
    .hole(top_hole_diameter)
    .edges("|Z")
    .chamfer(chamfer_distance)
)
